// src/utils/date-range.ts
function generateDateLabels(period) {
  const labels = [];
  const now = new Date;
  if (period === "month") {
    const formatter = new Intl.DateTimeFormat("en-US", { month: "long" });
    for (let m = 0;m < 12; m++) {
      const date2 = new Date(now.getFullYear(), m);
      labels.push(formatter.format(date2));
    }
  } else if (period === "week") {
    const seen = new Set;
    const date2 = new Date(now.getFullYear(), now.getMonth(), 1);
    while (date2.getMonth() === now.getMonth()) {
      const weekLabel = getISOWeekLabel(date2);
      if (!seen.has(weekLabel)) {
        seen.add(weekLabel);
        labels.push(weekLabel);
      }
      date2.setDate(date2.getDate() + 1);
    }
  } else {
    const formatter = new Intl.DateTimeFormat("en-GB", {
      day: "2-digit",
      month: "short"
    });
    const date2 = new Date(now.getFullYear(), now.getMonth(), 1);
    while (date2.getMonth() === now.getMonth()) {
      labels.push(formatter.format(date2));
      date2.setDate(date2.getDate() + 1);
    }
  }
  return labels;
}
function getISOWeekLabel(date2) {
  const tempDate = new Date(date2.getTime());
  tempDate.setHours(0, 0, 0, 0);
  const day = tempDate.getDay();
  tempDate.setDate(tempDate.getDate() + 4 - (day === 0 ? 7 : day));
  const yearStart = new Date(tempDate.getFullYear(), 0, 1);
  const weekNo = Math.ceil(((tempDate.getTime() - yearStart.getTime()) / 86400000 + 1) / 7);
  return `Week ${weekNo}`;
}

