var getSalesByPeriod = async (req, res) => {
  try {
    const period = req.query.period === "week" ? "week" : req.query.period === "day" ? "day" : "month";
    let dateTrunc = "month";
    let labelSQL = `to_char(date_trunc('month', o."createdAt"), 'FMMonth')`;
    let dateFilterSQL = `
      EXTRACT(YEAR FROM o."createdAt") = EXTRACT(YEAR FROM CURRENT_DATE)
    `;
    if (period === "week") {
      dateTrunc = "week";
      labelSQL = `('Week ' || to_char(date_trunc('week', o."createdAt"), 'FMWW'))`;
      dateFilterSQL = `
        DATE_TRUNC('month', o."createdAt") = DATE_TRUNC('month', CURRENT_TIMESTAMP AT TIME ZONE 'Africa/Lagos')
      `;
    } else if (period === "day") {
      dateTrunc = "day";
      labelSQL = `to_char(date_trunc('day', o."createdAt"), 'DD Mon')`;
      dateFilterSQL = `
        DATE_TRUNC('month', o."createdAt") = DATE_TRUNC('month', CURRENT_TIMESTAMP AT TIME ZONE 'Africa/Lagos')
      `;
    }
    const result = await db.execute(import_drizzle_orm7.sql.raw(`
        SELECT 
          ${labelSQL} AS label,
          SUM(oi."unitPrice" * oi."quantity")::numeric(10, 2) AS total
        FROM "orders" o
        JOIN "order_items" oi ON o."_id" = oi."orderId"
        WHERE ${dateFilterSQL}
          AND o."status" = 'delivered'   -- ✅ only successful orders
        GROUP BY label
        ORDER BY label
      `));
    const rows = result.rows;
    logger.info("Raw rows returned:", rows);
    const dataMap = new Map(rows.map((r) => [r.label.trim(), parseFloat(r.total)]));
    const allLabels = generateDateLabels(period);
    const responseData = {
      labels: allLabels,
      values: allLabels.map((label) => dataMap.get(label) || 0)
    };
    res.status(200).json({
      message: "Sales data fetched successfully",
      success: true,
      data: responseData
    });
  } catch (error) {
    logger.error("Metrics error:", error);
    throwServerError("Failed to fetch metrics");
  }
};

