var createOrder = async (req, res) => {
  try {
    const {
      name,
      address,
      telephone,
      email,
      note,
      deliveryMethod,
      promoCodeId
    } = req.body;
    let { items } = req.body;
    if (!name || !address || !telephone || !email) {
      throwBadRequest("All fields are required");
    }
    if (!["delivery", "pickup"].includes(deliveryMethod)) {
      throwBadRequest("Invalid delivery method. Must be 'delivery' or 'pickup'");
    }
    if (typeof items === "string") {
      try {
        items = JSON.parse(items);
      } catch {
        throwBadRequest("Invalid cart items format");
      }
    }
    if (!Array.isArray(items) || items.length === 0) {
      throwBadRequest("At least one cart item is required");
    }
    const orderId = generateHybridId("order");
    const internalId = $createId();
    await db.transaction(async (tx) => {
      const productIds = items.map((item) => item.productId);
      const productsInDB = await tx.select({
        id: products._id,
        stock: products.unit,
        price: products.price
      }).from(products).where(import_drizzle_orm8.inArray(products._id, productIds));
      let subtotal = 0;
      for (const item of items) {
        const product = productsInDB.find((p) => p.id === item.productId);
        if (!product) {
          throwBadRequest(`Product with ID ${item.productId} not found`);
        }
        if (product && product.stock < item.quantity) {
          throwBadRequest(`Not enough stock for product ${item.productId}`);
        }
        subtotal += parseFloat(item.unitPrice) * item.quantity;
      }
      let discountAmount = 0;
      let appliedPromoCodeId = null;
      if (promoCodeId) {
        const [promo] = await tx.select().from(promoCodes).where(import_drizzle_orm8.eq(promoCodes._id, promoCodeId));
        if (!promo || !promo.isActive) {
          throwBadRequest("Invalid or inactive promo code");
        }
        const discountValue = parseFloat(promo.discount);
        if (promo.isPercentage) {
          discountAmount = discountValue / 100 * subtotal;
        } else {
          discountAmount = discountValue;
        }
        if (discountAmount > subtotal) {
          discountAmount = subtotal;
        }
        appliedPromoCodeId = promo._id;
      }
      const total = subtotal - discountAmount;
      if (total < 0) {
        throwBadRequest("Calculated total is negative, something went wrong.");
      }
      await tx.insert(orders).values({
        _id: internalId,
        orderId,
        name,
        address,
        telephone,
        email,
        note: note || null,
        deliveryMethod,
        promoCodeId: appliedPromoCodeId,
        discountAmount: discountAmount.toFixed(2)
      });
      const orderItemsData = [];
      for (const item of items) {
        const product = productsInDB.find((p) => p.id === item.productId);
        if (product) {
          await tx.update(products).set({ unit: product.stock - item.quantity }).where(import_drizzle_orm8.eq(products._id, item.productId));
        }
        orderItemsData.push({
          _id: $createId(),
          orderId: internalId,
          productId: item.productId,
          quantity: item.quantity,
          unitPrice: item.unitPrice
        });
      }
      await tx.insert(orderItems).values(orderItemsData);
    });
    eventBus.emit("invoiceEmail", { orderId: internalId });
    res.status(201).json({
      success: true,
      message: "Order placed successfully",
      data: { orderId }
    });
  } catch (error) {
    handleControllerError(error, res, "Failed to create order");
  }
};
